        transparent 100%
    );
    animation: roy-ferrum-skeleton-circle 1.5s ease-in-out infinite;
}

@keyframes roy-ferrum-skeleton-circle {

    0%   { inset-inline-start: -100%; }
    100% { inset-inline-start: 100%; }

}

